SELECT CASE WHEN budget >= 4355000 THEN 'high' WHEN budget >= 1075000 THEN 'mid' ELSE 'low' END AS budget_bucket, dept_name, SUM(CASE WHEN location = 'London' THEN 1 ELSE 0 END) AS london_count FROM departments WHERE location = 'Singapore' AND dept_name IN ('HR', 'Sales', 'Finance') GROUP BY CASE WHEN budget >= 4355000 THEN 'high' WHEN budget >= 1075000 THEN 'mid' ELSE 'low' END, dept_name HAVING SUM(CASE WHEN location = 'London' THEN 1 ELSE 0 END) >= 31 ORDER BY dept_name, budget_bucket LIMIT 1;
